#ifndef WLED_SYNC_PROTO_H
#define WLED_SYNC_PROTO_H

// AI: below section was generated by an AI
/*
 * WLED sync protocol v2 - wire format (see docs/udp-sync-v2.md)
 *
 * A datagram is a SyncV2Header followed by payloadLen bytes of TLV sections (SyncV2Tlv + data).
 * All multi-byte fields are little-endian (native on all supported MCUs), structs are packed.
 * Receivers must skip unknown TLV types and only read the known prefix of a TLV that is longer than expected,
 * so fields can be appended without breaking older receivers.
 */

#include <stdint.h>

// first byte is non-ASCII and not used by any other protocol on the notifier port (0: legacy notifier, 1-5: UDP realtime,
// 0x9C: TPM2.NET, 255: node info, 'A'-'Z'/'{': UDP API), so legacy receivers ignore v2 datagrams
#define SYNC_V2_MAGIC0        0xA5
#define SYNC_V2_MAGIC1        'W'
#define SYNC_V2_MAGIC2        'S'
#define SYNC_V2_MAGIC3        '2'
#define SYNC_V2_VERSION       1

// message types
#define SYNC_V2_MSG_STATE     1  // full state (or one part of it)
#define SYNC_V2_MSG_STATE_REQ 2  // "please send your state": sent when joining
#define SYNC_V2_MSG_CLOCK     3  // header only: advertises the highest version (seq) seen, lets a (rebooted) node catch up

// header flags
#define SYNC_V2_FLAG_HEARTBEAT 0x01  // periodic re-send of an unchanged state
#define SYNC_V2_FLAG_RETRY     0x02  // repeated send of a recent change

// TLV types
#define SYNC_V2_TLV_GLOBAL    1  // SyncV2Global, in every STATE part
#define SYNC_V2_TLV_SEGMENT   2  // SyncV2Segment, one per segment
#define SYNC_V2_TLV_NODEINFO  3  // SyncV2NodeInfo, in part 0 of UDP STATE messages

#define SYNC_V2_GLOBAL_HAS_CCT 0x01  // SyncV2Global::flags: sender has a CCT capable bus, mainSeg CCT is valid

// maximum datagram sizes; arduino-esp32 WiFiUDP flushes every 1460 bytes, ESP-NOW payload is at most 250 bytes
#define SYNC_V2_MAX_UDP       1460
#define SYNC_V2_MAX_ESPNOW    250

struct __attribute__((packed)) SyncV2Header {
  uint8_t  magic[4];
  uint8_t  version;     // SYNC_V2_VERSION
  uint8_t  msgType;     // SYNC_V2_MSG_*
  uint8_t  flags;       // SYNC_V2_FLAG_*
  uint8_t  groups;      // sync groups (bit mapped) this message is for
  uint32_t sender;      // node id of the sender (derived from its MAC address)
  uint32_t origin;      // node id of the node where the change was made; (seq, origin) is the state's version
  uint32_t seq;         // Lamport clock value of the change
  uint8_t  part;        // index of this part (0..parts-1), a state is split by segments if it does not fit one datagram
  uint8_t  parts;       // number of parts of this state
  uint16_t payloadLen;  // number of TLV bytes following the header
};

struct __attribute__((packed)) SyncV2Tlv {
  uint8_t type;         // SYNC_V2_TLV_*
  uint8_t len;          // length of the data following this TLV header
};

struct __attribute__((packed)) SyncV2Global {
  uint8_t  bri;
  uint8_t  callMode;            // what triggered the change on the origin (informational)
  uint16_t transition;          // transition duration in ms
  uint8_t  nightlightActive;
  uint8_t  nightlightDelayMins;
  uint8_t  mainSeg;             // id of the main segment (applied to selected segments when not syncing segment options)
  uint8_t  flags;               // SYNC_V2_GLOBAL_*
  uint32_t timebase;            // millis() + strip.timebase at time of sending
  uint32_t timeSec;             // system time (unix seconds)
  uint16_t timeMs;
  uint8_t  timeSource;          // toki time source
  uint8_t  reserved;
  uint64_t segMask;             // bit n set: segment id n is active (all parts), used for segment bounds sync
};

struct __attribute__((packed)) SyncV2Segment {
  uint8_t  id;                  // real segment id (not compacted)
  uint8_t  grouping;
  uint8_t  spacing;
  uint8_t  opacity;
  uint16_t start;
  uint16_t stop;
  uint16_t startY;
  uint16_t stopY;
  uint16_t offset;
  uint16_t options;             // Segment::options
  uint8_t  mode;
  uint8_t  speed;
  uint8_t  intensity;
  uint8_t  palette;
  uint32_t colors[3];
  uint8_t  cct;
  uint8_t  custom1;
  uint8_t  custom2;
  uint8_t  custom3;             // bits 0-4: custom3, bits 5-7: check1-3
  uint8_t  blendMode;
};

struct __attribute__((packed)) SyncV2NodeInfo {
  char     name[32];            // server description, not necessarily NUL terminated
  uint32_t build;               // VERSION
  uint8_t  board;               // WLED_BOARD
  uint8_t  on;                  // bri > 0
};

static_assert(sizeof(SyncV2Header)   == 24, "SyncV2Header must be 24 bytes");
static_assert(sizeof(SyncV2Tlv)      ==  2, "SyncV2Tlv must be 2 bytes");
static_assert(sizeof(SyncV2Global)   == 28, "SyncV2Global must be 28 bytes");
static_assert(sizeof(SyncV2Segment)  == 37, "SyncV2Segment must be 37 bytes");
static_assert(sizeof(SyncV2NodeInfo) == 38, "SyncV2NodeInfo must be 38 bytes");
static_assert(sizeof(SyncV2Header) + 2*sizeof(SyncV2Tlv) + sizeof(SyncV2Global) + sizeof(SyncV2Segment) <= SYNC_V2_MAX_ESPNOW,
              "a STATE part with at least one segment must fit an ESP-NOW frame");
// AI: end

#endif // WLED_SYNC_PROTO_H
